/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'trnsconvqtdeww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Conversão Unidades de Medidas"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao1.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConOrigemDescricao = &uniConOrigemDescricao1 print printBlockFilteruniConOrigemDescricao EndIf Case &DynamicFiltersSelector1 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao1.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConDestinoDescricao = &uniConDestinoDescricao1 print printBlockFilteruniConDestinoDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao2.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConOrigemDescricao = &uniConOrigemDescricao2 print printBlockFilteruniConOrigemDescricao EndIf Case &DynamicFiltersSelector2 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao2.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConDestinoDescricao = &uniConDestinoDescricao2 print printBlockFilteruniConDestinoDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao3.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilteruniConOrigemDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConOrigemDescricao = &uniConOrigemDescricao3 print printBlockFilteruniConOrigemDescricao EndIf Case &DynamicFiltersSelector3 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao3.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilteruniConDestinoDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &uniConDestinoDescricao = &uniConDestinoDescricao3 print printBlockFilteruniConDestinoDescricao EndIf EndCase EndIf EndIf EndIf If not &TFuniConOrigemDescricao_Sel.IsEmpty() print printBlockTFuniConOrigemDescricao_Sel Else If not &TFuniConOrigemDescricao.IsEmpty() print printBlockTFuniConOrigemDescricao EndIf EndIf If not &TFuniConDestinoDescricao_Sel.IsEmpty() print printBlockTFuniConDestinoDescricao_Sel Else If not &TFuniConDestinoDescricao.IsEmpty() print printBlockTFuniConDestinoDescricao EndIf EndIf If not (&TFuniConvQtdeGerar.IsEmpty() AND &TFuniConvQtdeGerar_To.IsEmpty()) print printBlockTFuniConvQtdeGerar &TFuniConvQtdeGerar_To_Description = format('%1 (%2)', "Qtde a Gerar", "WWP_TSTo") print printBlockTFuniConvQtdeGerar_To EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsconvqtde order uniConOrigemDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (uniConOrigemDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order uniConDestinoDescricao when &OrderedBy = 2 AND &OrderedDsc = False order (uniConDestinoDescricao) when &OrderedBy = 2 AND &OrderedDsc = True order uniConvQtdeGerar when &OrderedBy = 3 AND &OrderedDsc = False order (uniConvQtdeGerar) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsconvqtdeWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &uniConOrigemDescricao1, &uniConDestinoDescricao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2 , &DynamicFiltersOperator2, &uniConOrigemDescricao2, &uniConDestinoDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &uniConOrigemDescricao3, &uniConDestinoDescricao3, &TFuniConOrigemDescricao, &TFuniConOrigemDescricao_Sel, &TFuniConDestinoDescricao, &TFuniConDestinoDescricao_Sel , &TFuniConvQtdeGerar, &TFuniConvQtdeGerar_To) Where prefCodigo = &prefCodigo
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsconvqtdeWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsconvqtdeWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsconvqtdeWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFUNICONORIGEMDESCRICAO" &TFuniConOrigemDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONORIGEMDESCRICAO_SEL" &TFuniConOrigemDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONDESTINODESCRICAO" &TFuniConDestinoDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONDESTINODESCRICAO_SEL" &TFuniConDestinoDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONVQTDEGERAR" &TFuniConvQtdeGerar.FromString(&GridStateFilterValue.Value) &TFuniConvQtdeGerar_To.FromString(&GridStateFilterValue.ValueTo) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
